'use client'

import { useState } from 'react'
import Link from 'next/link'
import { submitRentalRequest } from '../../services/rentalApi'
import { getProductImageUrl } from '../../services/productApi'
import { useStore } from '../../context/StoreContext'

const TENURE_OPTIONS = [
  { months: 1, label: '1 Month', discount: 0, tag: 'Short Term' },
  { months: 3, label: '3 Months', discount: 5, tag: '5% OFF' },
  { months: 6, label: '6 Months', discount: 10, tag: '10% OFF - Popular' },
  { months: 12, label: '12 Months', discount: 15, tag: '15% OFF - Best Value' },
]

export default function RentalBookingModal({
  isOpen,
  onClose,
  product,
  onSuccess,
}) {
  const { currentUser, openLoginModal } = useStore()
  const [durationMonths, setDurationMonths] = useState(1)
  const [startDate] = useState(() => new Date().toISOString().slice(0, 10))
  const [docType, setDocType] = useState('Aadhaar Card')
  const [docNumber, setDocNumber] = useState('')
  const [purpose, setPurpose] = useState('Personal / Professional')
  const [recipientName, setRecipientName] = useState(currentUser?.name || '')
  const [recipientPhone, setRecipientPhone] = useState(currentUser?.phone || currentUser?.mobile || '')
  const [address, setAddress] = useState('')
  const [city, setCity] = useState(currentUser?.city || 'Kanpur')
  const [pincode, setPincode] = useState('208001')
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [errorMsg, setErrorMsg] = useState('')
  const [submittedRental, setSubmittedRental] = useState(null)

  if (!isOpen) return null

  const baseMonthlyRent = Number(product?.price || product?.rentPrice || 1999)
  const selectedOption = TENURE_OPTIONS.find((t) => t.months === durationMonths) || TENURE_OPTIONS[0]
  const discountMultiplier = 1 - selectedOption.discount / 100
  const effectiveMonthlyRent = Math.round(baseMonthlyRent * discountMultiplier)
  const totalRentAmount = effectiveMonthlyRent * durationMonths
  const securityDeposit = Math.round(effectiveMonthlyRent * 1.5)
  const totalInitialPay = effectiveMonthlyRent + securityDeposit

  // Compute calculated end date
  const calcEndDate = new Date(startDate)
  calcEndDate.setMonth(calcEndDate.getMonth() + durationMonths)
  const formattedEndDate = calcEndDate.toLocaleDateString('en-IN', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
  })

  const handleSubmit = async (e) => {
    e.preventDefault()

    if (!currentUser) {
      setErrorMsg('Please log in to submit a rental application.')
      openLoginModal?.()
      return
    }

    if (!recipientName.trim()) {
      setErrorMsg('Please enter customer full name.')
      return
    }
    if (!recipientPhone.trim()) {
      setErrorMsg('Please enter mobile contact number.')
      return
    }
    if (!docNumber.trim()) {
      setErrorMsg('Please enter your ID document number for KYC verification.')
      return
    }

    setIsSubmitting(true)
    setErrorMsg('')

    try {
      const payload = {
        productId: product?.id || product?._id,
        productTitle: product?.title || product?.name || 'Prestige Rental Hardware',
        productImage: product?.image || product?.images?.[0] || product?.imageUrl || '',
        productSpecs: product?.specs || 'Prestige Certified Hardware',
        tenureType: 'monthly',
        duration: durationMonths,
        startDate,
        rentAmountPerUnit: effectiveMonthlyRent,
        totalRentAmount,
        securityDeposit,
        customer: {
          name: recipientName.trim(),
          email: currentUser.email || '',
          phone: recipientPhone.trim(),
          address: address.trim() || 'Civil Lines, VIP Road',
          city: city.trim() || 'Kanpur',
          state: 'Uttar Pradesh',
          postalCode: pincode.trim() || '208001',
        },
        kycDetails: {
          documentType: docType,
          documentNumber: docNumber.trim(),
          purpose,
        },
      }

      const res = await submitRentalRequest(payload)
      setSubmittedRental(res)
      onSuccess?.(res)
    } catch (err) {
      setErrorMsg(err.message || 'Failed to submit rental request. Please try again.')
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-xs p-3 sm:p-4 overflow-y-auto">
      <div className="w-full max-w-xl bg-white rounded-2xl shadow-2xl border border-[#e5e7eb] overflow-hidden my-auto max-h-[94vh] flex flex-col animate-fade-in">
        {/* Header */}
        <div className="flex items-center justify-between px-5 sm:px-6 py-4 border-b border-[#f1f5f9] bg-[#fafbfc]">
          <div>
            <div className="flex items-center gap-2">
              <span className="w-2.5 h-2.5 rounded-full bg-[#dc1414] animate-pulse" />
              <h3 className="text-base sm:text-lg font-extrabold text-[#111827]">
                Rent Hardware Lease Agreement
              </h3>
            </div>
            <p className="text-xs text-[#6b7280] mt-0.5">
              Doorstep delivery &bull; Zero maintenance &bull; 100% refundable deposit
            </p>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-xl text-[#9ca3af] hover:text-[#111827] hover:bg-gray-100 transition-colors cursor-pointer"
          >
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        {/* Content Body */}
        <div className="p-5 sm:p-6 overflow-y-auto space-y-5">
          {submittedRental ? (
            <div className="text-center py-6 space-y-4">
              <div className="w-16 h-16 rounded-full bg-emerald-50 text-emerald-600 flex items-center justify-center mx-auto border border-emerald-200">
                <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M5 13l4 4L19 7" />
                </svg>
              </div>
              <div>
                <h4 className="text-lg font-extrabold text-[#111827]">
                  Rental Application Submitted!
                </h4>
                <p className="text-sm font-semibold text-[#dc1414] mt-1 font-mono">
                  Agreement #{submittedRental.rentalId}
                </p>
                <p className="text-xs text-[#6b7280] max-w-sm mx-auto mt-2 leading-relaxed">
                  Our Kanpur fulfillment team has received your application. Your KYC verification will be processed within 2-4 hours, after which hardware dispatch is initiated.
                </p>
              </div>

              <div className="bg-[#f8fafc] p-4 rounded-xl border border-[#f1f5f9] text-xs space-y-2 text-left max-w-md mx-auto">
                <div className="flex justify-between">
                  <span className="text-[#6b7280]">Device:</span>
                  <strong className="text-[#111827]">{submittedRental.productSnapshot?.title}</strong>
                </div>
                <div className="flex justify-between">
                  <span className="text-[#6b7280]">Tenure:</span>
                  <strong className="text-[#111827]">{submittedRental.duration} Months (Until {formattedEndDate})</strong>
                </div>
                <div className="flex justify-between">
                  <span className="text-[#6b7280]">Monthly Rent:</span>
                  <strong className="text-[#dc1414]">₹{Number(submittedRental.rentAmountPerUnit).toLocaleString('en-IN')}/mo</strong>
                </div>
                <div className="flex justify-between">
                  <span className="text-[#6b7280]">Refundable Deposit:</span>
                  <strong className="text-emerald-700">₹{Number(submittedRental.securityDeposit).toLocaleString('en-IN')}</strong>
                </div>
              </div>

              <div className="pt-2 flex items-center justify-center gap-3">
                <Link
                  href="/profile?tab=rentals"
                  onClick={onClose}
                  className="px-5 py-2.5 rounded-xl bg-[#dc1414] hover:bg-[#b91c1c] text-white text-xs font-bold transition-all shadow-sm"
                >
                  View My Rental Dashboard →
                </Link>
                <button
                  type="button"
                  onClick={onClose}
                  className="px-4 py-2.5 rounded-xl border border-[#d1d5db] text-xs font-bold text-[#374151] hover:bg-gray-50"
                >
                  Done
                </button>
              </div>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="space-y-4">
              {errorMsg && (
                <div className="p-3 rounded-xl bg-red-50 border border-red-200 text-xs text-[#dc1414] font-medium flex items-center gap-2">
                  <svg className="w-4 h-4 shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                  </svg>
                  <span>{errorMsg}</span>
                </div>
              )}

              {/* Hardware Summary Card */}
              <div className="flex items-center gap-3.5 bg-[#f8fafc] p-3.5 rounded-xl border border-[#f1f5f9]">
                <img
                  src={product?.image || product?.imageUrl ? getProductImageUrl(product.image || product.imageUrl) : '/placeholder-product.png'}
                  alt={product?.title || product?.name}
                  className="w-14 h-14 rounded-lg object-contain bg-white border border-[#e5e7eb] shrink-0 p-1"
                />
                <div className="flex-1 min-w-0">
                  <h4 className="text-xs sm:text-sm font-bold text-[#111827] truncate">
                    {product?.title || product?.name || 'Prestige Certified System'}
                  </h4>
                  <p className="text-[11px] text-[#6b7280] truncate mt-0.5">
                    {product?.specs || 'High Performance Certified Hardware'}
                  </p>
                  <p className="text-xs font-extrabold text-[#dc1414] mt-1">
                    ₹{effectiveMonthlyRent.toLocaleString('en-IN')}/mo
                    {selectedOption.discount > 0 && (
                      <span className="ml-2 text-[10px] text-emerald-700 font-bold bg-emerald-50 px-1.5 py-0.5 rounded border border-emerald-200">
                        {selectedOption.tag}
                      </span>
                    )}
                  </p>
                </div>
              </div>

              {/* Lease Tenure Selection */}
              <div>
                <label className="block text-xs font-bold uppercase tracking-wider text-[#374151] mb-2">
                  Select Rental Duration
                </label>
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
                  {TENURE_OPTIONS.map((opt) => (
                    <button
                      key={opt.months}
                      type="button"
                      onClick={() => setDurationMonths(opt.months)}
                      className={`py-2 px-2.5 rounded-xl border text-center transition-all cursor-pointer ${
                        durationMonths === opt.months
                          ? 'border-[#dc1414] bg-[#fee2e2]/30 ring-2 ring-[#dc1414]/20'
                          : 'border-[#e5e7eb] bg-white hover:border-[#dc1414]/40'
                      }`}
                    >
                      <span className="block text-xs font-bold text-[#111827]">{opt.label}</span>
                      <span className={`block text-[10px] font-semibold mt-0.5 ${opt.discount > 0 ? 'text-[#dc1414]' : 'text-[#6b7280]'}`}>
                        {opt.tag}
                      </span>
                    </button>
                  ))}
                </div>
                <p className="text-[11px] text-[#6b7280] mt-1.5">
                  Lease Return Date: <strong className="text-[#111827]">{formattedEndDate}</strong> (extendable anytime).
                </p>
              </div>

              {/* Delivery Contact Details */}
              <div className="space-y-2.5 pt-1">
                <label className="block text-xs font-bold uppercase tracking-wider text-[#374151]">
                  Delivery Recipient &amp; Contact
                </label>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                  <input
                    type="text"
                    value={recipientName}
                    onChange={(e) => setRecipientName(e.target.value)}
                    placeholder="Full Name *"
                    className="w-full px-3 py-2 rounded-xl border border-[#d1d5db] text-xs focus:border-[#dc1414] outline-none"
                    required
                  />
                  <input
                    type="tel"
                    value={recipientPhone}
                    onChange={(e) => setRecipientPhone(e.target.value)}
                    placeholder="Mobile Phone Number *"
                    className="w-full px-3 py-2 rounded-xl border border-[#d1d5db] text-xs focus:border-[#dc1414] outline-none"
                    required
                  />
                </div>
                <div className="grid grid-cols-3 gap-2.5">
                  <input
                    type="text"
                    value={address}
                    onChange={(e) => setAddress(e.target.value)}
                    placeholder="Street Address"
                    className="col-span-2 px-3 py-2 rounded-xl border border-[#d1d5db] text-xs focus:border-[#dc1414] outline-none"
                  />
                  <input
                    type="text"
                    value={pincode}
                    onChange={(e) => setPincode(e.target.value)}
                    placeholder="PIN Code"
                    className="px-3 py-2 rounded-xl border border-[#d1d5db] text-xs focus:border-[#dc1414] outline-none"
                  />
                </div>
              </div>

              {/* KYC Document Verification */}
              <div className="space-y-2.5 pt-1">
                <label className="block text-xs font-bold uppercase tracking-wider text-[#374151]">
                  KYC Verification Details
                </label>
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-2.5">
                  <select
                    value={docType}
                    onChange={(e) => setDocType(e.target.value)}
                    className="px-3 py-2 rounded-xl border border-[#d1d5db] text-xs focus:border-[#dc1414] outline-none bg-white font-medium"
                  >
                    <option value="Aadhaar Card">Aadhaar Card</option>
                    <option value="PAN Card">PAN Card</option>
                    <option value="Voter ID">Voter ID</option>
                    <option value="Company GSTIN">Company GSTIN</option>
                  </select>
                  <input
                    type="text"
                    value={docNumber}
                    onChange={(e) => setDocNumber(e.target.value)}
                    placeholder="ID / Document Number *"
                    className="sm:col-span-2 px-3 py-2 rounded-xl border border-[#d1d5db] text-xs focus:border-[#dc1414] outline-none"
                    required
                  />
                </div>
              </div>

              {/* Pricing Breakdown Card */}
              <div className="bg-[#f8fafc] p-3.5 rounded-xl border border-[#f1f5f9] text-xs space-y-1.5">
                <div className="flex justify-between">
                  <span className="text-[#6b7280]">First Month Rent ({durationMonths} Mo Plan)</span>
                  <span className="font-bold text-[#111827]">₹{effectiveMonthlyRent.toLocaleString('en-IN')}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-[#6b7280]">Refundable Security Deposit</span>
                  <span className="font-bold text-emerald-700">₹{securityDeposit.toLocaleString('en-IN')} (Refundable)</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-[#6b7280]">Doorstep Delivery &amp; Setup</span>
                  <span className="font-bold text-emerald-700">FREE</span>
                </div>
                <div className="flex justify-between pt-1.5 border-t border-[#e2e8f0] font-bold text-sm">
                  <span className="text-[#111827]">Initial Payable at Delivery</span>
                  <span className="text-[#dc1414]">₹{totalInitialPay.toLocaleString('en-IN')}</span>
                </div>
              </div>

              {/* Submit CTA */}
              <div className="pt-2">
                <button
                  type="submit"
                  disabled={isSubmitting}
                  className="w-full py-3 bg-[#dc1414] hover:bg-[#b91c1c] active:scale-[0.99] text-white text-sm font-bold rounded-xl shadow-[0_4px_14px_rgba(220,20,20,0.35)] transition-all flex items-center justify-center gap-2 cursor-pointer disabled:opacity-60"
                >
                  {isSubmitting ? (
                    <>
                      <svg className="w-4 h-4 animate-spin" viewBox="0 0 24 24" fill="none">
                        <circle cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" className="opacity-25" />
                        <path fill="currentColor" d="M4 12a8 8 0 018-8v8H4z" className="opacity-75" />
                      </svg>
                      <span>Submitting Rental Application...</span>
                    </>
                  ) : (
                    <>
                      <span>Submit Rental Request</span>
                      <span>→</span>
                    </>
                  )}
                </button>
              </div>
            </form>
          )}
        </div>
      </div>
    </div>
  )
}
